   notKu:'Ji Fransî (bi nazalizasyona -an-): bi mana pêşê artêşê; di hunerê de hereketên ceribandin û radikal (Dada, Surrealism, Futurism). Hîn jî forma deynkirî ya Fransî parastiye.',
