   notKu:'Latînî reliquiae (bermayî): (1) tiştê kevnar ê bi-nirx ku ji demekê maye; (2) rêzgirtî, parçeyê pîroz ê pîrozekî; (3) mecazî: tiştê ji serdemeke din maye.',
