   herKu:['Wan pîrozbahiyeke êl-îsyan kir.', 'Elaleta êl-îsyan pencereyan şkandin.'], emoji:'🔥'),

  (id:'en_c2_236', en:'chaotic', ku:'kaotîk', ipa:'/keɪˈɒtɪk/', pos:'adj',
   form:null, kat:'akademîk', zor:0.40,
   notKu:'Kaotîk. Bêîntîzam û tevlihev.',
