   herKu:['Ode kaotîk bû.', 'Rewş kaotîk bû.'], emoji:'🌀'),

  (id:'en_c2_237', en:'anarchic', ku:'bêqanûn', ipa:'/əˈnɑːkɪk/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Bêqanûn. Bêyî qanûn û nîzam.',
