   herKu:['Welat ket kaosa bêqanûn.', 'Rewşa bêqanûn dom kir.'], emoji:'💥'),

  (id:'en_c2_238', en:'quintessential', ku:'ciwandar', ipa:'/ˌkwɪntɪˈsenʃəl/', pos:'adj',
   form:null, kat:'edebî', zor:0.65,
   notKu:'Ciwandar. Ya herî bipêwist û esas.',
   her:["She is the quintessential teacher.", "This is the quintessential example."],
   herKu:['Ew mamosteya ciwandar e.', 'Ev nimûneya ciwandar e.'], emoji:'🎯'),

  (id:'en_c2_239', en:'paramount', ku:'sereke-bilindtir', ipa:'/ˈpærəmaʊnt/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Ji Anglo-Fransî par amunt (li ser, li jorî): ya li hemiyan serde, ya herî bilind. Collocation bi "importance" û "concern". Hevkirpanî: of paramount importance (standart deyim).',
   her:['In aviation, passenger safety is of paramount importance.', 'The judge ruled that the child\'s welfare must be paramount.'],
   herKu:['Di firînê de, ewlehiya rêwîyan sereke-bilindtir e.', 'Dadger biryar da ku rehetiya zarok pêdivî ye ku sereke-bilindtir be.'], emoji:'👑'),

  (id:'en_c2_240', en:'preeminent', ku:'pêşîn', ipa:'/priˈemɪnənt/', pos:'adj',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Pêşîn. Ya herî girîng û balkêş.',
   her:["She is the preeminent scholar in her field.", "He has a preeminent position."],
   herKu:['Ew zanyara pêşîn a di qada xwe de ye.', 'Wî pozîsyoneke pêşîn heye.'], emoji:'🥇'),

  (id:'en_c2_241', en:'quixotic', ku:'xeyalperest-asîl', ipa:'/kwɪkˈsɒtɪk/', pos:'adj',
   form:null, kat:'edebî', zor:0.70,
   notKu:'Ji Don Quixote, qehremanê Cervantes (1605/1615). Xeyalperest-asîl: bi armancên nêzîkê nerastiyê lê bi dilsoziyeke esîl. Connotation: nerm-rewa, carinan dilşewat, ne-bi-tevahî neyînî.',
   her:['His quixotic quest to restore the old printing press was doomed from the start.', 'Her quixotic idealism endeared her to students but frustrated administrators.'],
   herKu:['Gerekî wî ya xeyalperest-asîl ji bo saxkirina çapxaneya kevnar ji destpêkê ve mehkûm bû.', 'Îdealîzma wê ya xeyalperest-asîl ew ji xwendekaran re delal kir lê rêveberan bêhêvî kir.'], emoji:'🎭'),

  (id:'en_c2_242', en:'Pyrrhic', ku:'bi-xisara-mezin-serketî', ipa:'/ˈpɪrɪk/', pos:'adj',
   form:null, kat:'edebî', zor:0.70,
   notKu:'Ji navê King Pyrrhus of Epirus (MÎ 319-272), yê ku li dijî Romayê du serketinên bi xisareke wisa mezin bi dest xist ku got: "Serketineke din a bi vî rengî min hilweşîne." Hema her dem bi "victory" tê hev-bikaranîn.',
   her:['The court ruling was a Pyrrhic victory — they won the case but lost their reputation.', 'Napoleon\'s capture of Moscow in 1812 proved a Pyrrhic victory.'],
   herKu:['Biryara dadgehê bi-xisara-mezin-serketinek bû — wan doz birin lê nav û dengê xwe winda kirin.', 'Girtina Napolyon a Moskovayê di 1812 de serketineke bi-xisara-mezin derket.'], emoji:'⚔️'),

  (id:'en_c2_243', en:'halcyon', ku:'xweş-aram', ipa:'/ˈhælsiən/', pos:'adj',
   form:null, kat:'edebî', zor:0.70,
   notKu:'Xweş-aram. Dema aram û xweş.',
   her:["Those were the halcyon days of our youth.", "She remembered the halcyon summers."],
   herKu:['Ew rojên xweş-aram ên ciwaniya me bûn.', 'Wê havînên xweş-aram bîr anîn.'], emoji:'🌅'),

  (id:'en_c2_244', en:'Sisyphean', ku:'bêdawî-zehmet', ipa:'/ˌsɪsɪˈfiːən/', pos:'adj',
   form:null, kat:'edebî', zor:0.75,
   notKu:'Ji mîtolojiya Yewnanî: Sisyphus bi cezayê êbedî hat mehkûm kirin ku kevirekî giran li çiyê hilbike, ew kevir her car vegere. Camus eseya xwe "Le Mythe de Sisyphe" (1942) li ser vê nivîsand. Karekî bêdawî û bê-encam.',
   her:['For Camus, raising a boulder up a hill forever is the Sisyphean condition of human existence.', 'Trying to teach cats obedience feels like a Sisyphean task.'],
   herKu:['Ji bo Camus, hildana kevirekî li çiyê ya êbedî rewşa bêdawî-zehmet a hebûna mirov e.', 'Hewldana hînkirina guhdariyê ya pisîkan wek peywireke bêdawî-zehmet tê hîs kirin.'], emoji:'🪨'),

  (id:'en_c2_245', en:'panacea', ku:'derman-hemû', ipa:'/ˌpænəˈsiːə/', pos:'n',
   form:null, kat:'edebî', zor:0.65,
   notKu:'Ji Yewnanî pan (hemû) + akos (derman); Panacea xwedawenda saxkirinê bû. Çareseriya hêvîkirî ya hemû pirsgirêkan — pirî caran bi tonek şîkdar tê bikaranîn ("there is no panacea").',
   her:['AI is no panacea for the education system\'s deep-rooted problems.', 'The IMF\'s structural adjustment programs were touted as a panacea but often deepened inequality.'],
   herKu:['AI ne derman-hemû ye ji bo pirsgirêkên kûr-rîkek ên sîstema perwerdehiyê.', 'Bernameyên sazkirina strukturî yên IMF wek derman-hemû hatin pesindan lê pirî caran newekheviyê kûrtir kirin.'], emoji:'💊'),

  (id:'en_c2_246', en:'zeitgeist', ku:'rih-serdem', ipa:'/ˈzaɪtɡaɪst/', pos:'n',
   form:null, kat:'akademîk', zor:0.70,
   notKu:'Ji Almanî Zeit (dem) + Geist (rih/gan): ruhê serdemê, kargêrên hişmendî yên dema diyar. Têgeha Hegelî ye. Di Îngilîzî de, tîpa z- bi-kîtan paşê tê xwendin.',
   her:['Orwell\'s "1984" captured the post-war zeitgeist of surveillance anxiety.', 'TikTok has become the defining medium of Gen Z\'s zeitgeist.'],
   herKu:['"1984"-a Orwell rih-serdem-a piştî-şer ya xemgîniya çavdêriyê girt.', 'TikTok bûye medya-naskirî ya rih-serdem-a Nifşa Z.'], emoji:'⏰'),

  (id:'en_c2_247', en:'schadenfreude', ku:'kêf-ji-êşa-yên-din', ipa:'/ˈʃɑːdənfrɔɪdə/', pos:'n',
   form:null, kat:'edebî', zor:0.75,
   notKu:'Ji Almanî Schaden (ziyan) + Freude (kêf). Bi wateya kêfa ji neserkeftina kesekî din — pirî caran bi pir sivikî dizanînî bê connotation ya pir xirab lê dîsa jî neyînî.',
   her:['He felt a guilty pang of schadenfreude at his rival\'s very public failure.', 'Germans invented the word schadenfreude because no English equivalent existed.'],
   herKu:['Wî li ser têkçûna hevrikê xwe ya eşkere kêfeke gunehkar a kêf-ji-êşa-yên-din hîs kir.', 'Almanan peyva schadenfreude afirandin ji ber ku tu hevwateya Îngilîzî ya wê tunebû.'], emoji:'😏'),

  (id:'en_c2_248', en:'ubiquitous', ku:'her-cî', ipa:'/juːˈbɪkwɪtəs/', pos:'adj',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Latînî ubique (li her derê): hema li her cî heye; wisa belav ku nediyar bûye. Register: formal/academic, nêzîkê omnipresent.',
   her:['Surveillance cameras have become ubiquitous in urban centres.', 'The ubiquitous smartphone has transformed how we consume information.'],
   herKu:['Kamerayên çavdêriyê li navendên bajarî bûne her-cî.', 'Telefona biaqil a her-cî awayê me yê pejirandina agahî guherandiye.'], emoji:'📱'),

  (id:'en_c2_249', en:'serendipity', ku:'rasthatina-xweş', ipa:'/ˌserənˈdɪpəti/', pos:'n',
   form:null, kat:'edebî', zor:0.65,
   notKu:'Horace Walpole di 1754 de peyvek nû afirand ji çîroka "The Three Princes of Serendip" (Serendip = navê Farisî ya kevnar ê Sri Lanka): kabiliyeta dîtina tiştên biha bi tesadufî. Hevwate: happy accident.',
   her:['The discovery of penicillin was a classic case of scientific serendipity.', 'She met her future spouse through pure serendipity at a bus stop.'],
   herKu:['Vedîtina penîsîlînê nimûneyeke klasîk a rasthatina-xweş a zanistî bû.', 'Wê hevjîna xwe ya pêşeroja bi rasthatina-xweş li stasyona otobûsê dît.'], emoji:'🍀'),

  (id:'en_c2_250', en:'ephemera', ku:'demkurt-tişt', ipa:'/ɪˈfemərə/', pos:'n',
   form:null, kat:'edebî', zor:0.70,
   notKu:'Demkurt-tişt. Tiştên ku demek kurt dimînin.',
   her:["She collected ephemera from the war.", "Postcards are a form of ephemera."],
   herKu:['Wê demkurt-tişt ji şer kom kir.', 'Postekart şêweyeke demkurt-tişt e.'], emoji:'📮'),

  (id:'en_c2_251', en:'empirical', ku:'ezmûnî', ipa:'/ɪmˈpɪrɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.50,
   notKu:'Li ser ezmûn û çavdêriyê hatî damezirandin.',
