   herKu:['Teorî hewceyî delîlên ezmûnî ye.', 'Lêkolîna ezmûnî ji texmînê pêbawertir e.'], emoji:'📊'),

  (id:'en_c2_252', en:'theoretical', ku:'teorîk', ipa:'/ˌθɪəˈretɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.45,
   notKu:'Ya li ser teoriyê ava bûyî.',
   her:["She studies theoretical physics.", "The theoretical framework needs revision."],
   herKu:['Ew fîzîka teorîk dixwîne.', 'Çarçoveya teorîk hewceyî guhertinê ye.'], emoji:'🧠'),

  (id:'en_c2_253', en:'hypothetical', ku:'hîpotetîk', ipa:'/ˌhaɪpəˈθetɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.50,
   notKu:'Li ser texmînê ava bûyî. Nediyar.',
