   herKu:['Vê senaryoya hîpotetîk binirxîne.', 'Nîqaş tenê hîpotetîk ma.'], emoji:'❓'),

  (id:'en_c2_254', en:'conceptual', ku:'têgehî', ipa:'/kənˈseptʃuəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.50,
