   form:null, kat:'akademîk', zor:0.50,
   notKu:'Bi îdeolojiyê ve girêdayî.',
   her:["Ideological differences divided the party.", "She avoids ideological debates."],
   herKu:['Ciyawaziyên îdeolojîk partî parçe kir.', 'Ew ji nîqaşên îdeolojîk dûr dikeve.'], emoji:'⚖️'),

  (id:'en_c2_257', en:'methodological', ku:'metodolojîk', ipa:'/ˌmeθədəˈlɒdʒɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Bi rêbaznasiyê ve girêdayî.',
   her:["The study has methodological flaws.", "Methodological rigor is essential in research."],
   herKu:['Lêkolîn xwedî kêmasiyên metodolojîk e.', 'Hişkiya metodolojîk di lêkolînê de bingehîn e.'], emoji:'🔬'),

  (id:'en_c2_258', en:'epistemological', ku:'epîstemolojîk', ipa:'/ɪˌpɪstəməˈlɒdʒɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.65,
   notKu:'Bi teoriya zanînê ve girêdayî.',
   her:["He raised epistemological questions about knowledge.", "The epistemological debate continues among philosophers."],
   herKu:['Wî pirsên epîstemolojîk derbarê zanînê de rakirin.', 'Nîqaşa epîstemolojîk di nav fîlozofan de berdewam e.'], emoji:'📚'),

  (id:'en_c2_259', en:'ontological', ku:'ontolojîk', ipa:'/ˌɒntəˈlɒdʒɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.65,
   notKu:'Bi teoriya heyînê ve girêdayî.',
   her:["The ontological argument proves existence.", "She studies ontological categories in philosophy."],
   herKu:['Arguminta ontolojîk heyînê îspat dike.', 'Ew kategoriyên ontolojîk di felsefeyê de dixwîne.'], emoji:'🌌'),

  (id:'en_c2_260', en:'phenomenological', ku:'fenomenolojîk', ipa:'/fɪˌnɒmɪnəˈlɒdʒɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.65,
   notKu:'Bi fenomenolojiyê ve girêdayî.',
