   herKu:['Analîza wî ya fenomenolojîk hişmendiyê lêdikole.', 'Lêkolîna fenomenolojîk li ser ezmûna jiyayî disekine.'], emoji:'👁️'),

  (id:'en_c2_261', en:'hermeneutic', ku:'hermenotîk', ipa:'/ˌhɜːməˈnjuːtɪk/', pos:'adj',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Bi zanista şirovekirinê ve girêdayî.',
   her:["The hermeneutic approach interprets texts deeply.", "She applies hermeneutic methods to ancient manuscripts."],
   herKu:['Nêzîkatiya hermenotîk metnan kûr şirove dike.', 'Ew rêbazên hermenotîk li destnivîsên kevnar disepîne.'], emoji:'📜'),

  (id:'en_c2_262', en:'dialectical', ku:'diyalektîk', ipa:'/ˌdaɪəˈlektɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Bi diyalektîkê ve girêdayî.',
   her:["Marx developed a dialectical method.", "Their dialectical reasoning impressed the audience."],
   herKu:['Marx rêbazeke diyalektîk pêşxist.', 'Ramîna wan a diyalektîk temaşevan şaş kir.'], emoji:'🔁'),

  (id:'en_c2_263', en:'dialectic', ku:'diyalektîk', ipa:'/ˌdaɪəˈlektɪk/', pos:'n',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Diyalektîk. Rêbaza gengeşiyê.',
