   herKu:['Diyalektîka Hegelî felsefeya nûjen şikil da.', 'Diyalektîka navbera teorî û pratîkê berdewam e.'], emoji:'⚖️'),

  (id:'en_c2_264', en:'polemic', ku:'polemîk', ipa:'/pəˈlemɪk/', pos:'n',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Polemîk. Gengeşiyeke tund.',
   her:["Her book is a polemic against capitalism.", "He wrote a fierce polemic in response."],
   herKu:['Pirtûka wê polemîkek li dijî kapîtalîzmê ye.', 'Wî di bersivê de polemîkeke tund nivîsand.'], emoji:'🗣️'),

  (id:'en_c2_265', en:'polemical', ku:'polemîkî', ipa:'/pəˈlemɪkəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Polemîkî. Nîqaşkar.',
   her:["His polemical style alienated many readers.", "She wrote a polemical essay on feminism."],
   herKu:['Şêwaza wî ya polemîkî gelek xwîner dûr xistin.', 'Wê gotareke polemîkî li ser femînîzmê nivîsand.'], emoji:'⚔️'),

  (id:'en_c2_266', en:'panegyric', ku:'pesindarî', ipa:'/ˌpænɪˈdʒɪrɪk/', pos:'n',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Pesindariya zêde. Medhiyenivîsî.',
   her:["The speech was a panegyric to the king.", "Critics dismissed the article as mere panegyric."],
   herKu:['Axaftin pesindariya padîşah bû.', 'Rexnegiran gotar wek pesindariyeke tazî red kir.'], emoji:'👑'),

  (id:'en_c2_267', en:'eulogy', ku:'şînname', ipa:'/ˈjuːlədʒi/', pos:'n',
   form:null, kat:'akademîk', zor:0.50,
   notKu:'Şînname. Axaftina pesindarî ji bo mirî.',
