   herKu:['Wî di merasîmê de şînnameyeke bandorker pêşkêş kir.', 'Şînnameya wê hemû kesên amade bi hêsir kir.'], emoji:'🕊️'),

  (id:'en_c2_268', en:'elegiac', ku:'elegî', ipa:'/ˌelɪˈdʒaɪək/', pos:'adj',
   form:null, kat:'akademîk', zor:0.55,
   notKu:'Elegî. Xemgîn û şînbar.',
   her:["The poem has an elegiac tone throughout.", "His elegiac memoir recalls lost friends."],
   herKu:['Helbest di tevahiyê de awazeke elegî heye.', 'Bîrhatina wî ya elegî hevalên wendayî tîne bîrê.'], emoji:'🌙'),

  (id:'en_c2_269', en:'encomiastic', ku:'medhiyekar', ipa:'/enˌkəʊmɪˈæstɪk/', pos:'adj',
   form:null, kat:'akademîk', zor:0.65,
   notKu:'Medhiyekar. Bi pesindarî.',
   her:["The review was highly encomiastic in tone.", "His encomiastic remarks praised her achievements."],
   herKu:['Nirxandin di awazê de pir medhiyekar bû.', 'Gotinên wî yên medhiyekar serkeftinên wê pesend kirin.'], emoji:'🏆'),

  (id:'en_c2_270', en:'vituperative', ku:'dijûnkar', ipa:'/vɪˈtjuːpərətɪv/', pos:'adj',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Dijûnkar. Bi gotinên tund û sêhr.',
