  (id:'en_c2_271', en:'denunciatory', ku:'şermzarker', ipa:'/dɪˈnʌnsiətəri/', pos:'adj',
   form:null, kat:'akademîk', zor:0.60,
   notKu:'Şermzarker. Tawanbarkirî.',
