   herKu:['Senator axaftineke şermzarker pêşkêş kir.', 'Awazê wê yê şermzarker zû dijmin çêkirin.'], emoji:'📢'),

  (id:'en_c2_272', en:'censorious', ku:'rexnegirker', ipa:'/senˈsɔːriəs/', pos:'adj',
