  (id:'en_c2_482', en:'apocryphal', ku:'şîkdar-ne-rast', ipa:'/əˈpɒkrɪfəl/', pos:'adj',
   form:null, kat:'akademîk', zor:0.65,
   notKu:'Ji Yewnanî apokruphos (veşartî); tê ji Apokrîfa dînî ya ne-kanonîk. Îro: çîroka belavbûyî lê ya ku rastiya wê şîkdar e, di îhtîmal de îcadkirî.',
