   form:null, kat:'akademîk', zor:0.60,
   notKu:'Ji Yewnanî hēgemonia (serokatî). Di siyasetnasiyê: serdestiya welatekî li ser yên din. Li cem Antonio Gramsci (1930an): "hegemoniya çandî" — serdestiya ramanî ya çînên serdest ku wek "sense-ya giştî" tê qebûl kirin.',
