  (id:'en_c2_661', en:'solipsism', ku:'tenê-ez-im', ipa:'/ˈsɒlɪpsɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.60,
   notKu:'Ji Latînî solus (tenê) + ipse (xwe): ramana felsefî ya ku tenê hişê xwe tê îspat kirin ku heye; her tişê din dikare xewn be. Tîpa ekstrem ya şik-parêziyê; Descartes wê teşxîs kir lê red kir. Pirî caran wek rexne tê bikaranîn ji bo xwepersendiyê.',
