   herKu:['Tenê-ez-imê fîlmê—bê tu karakterekî ji bilî vebêjer—temaşevan dijber dike.', 'Wittgenstein got ku zimanekî taybet dê tenê-ez-imiyê bidin.'], emoji:'🪞'),

  (id:'en_c2_662', en:'catharsis', ku:'paqijbûna-hestî', ipa:'/kəˈθɑːsɪs/', pos:'n',
