   notKu:'Ji Yewnanî katharsis (paqijkirin). Aristoteles di "Poetics"-ê de: armanca trajediyê paqijkirina hestên tirsê û rehmê ye. Di psîkanalîzê de (Breuer, Freud): berdana hesten nefsanî. UK: /kəˈθɑːsɪs/; US: /kəˈθɑːrsɪs/.',
   her:['For Aristotle, Greek tragedy achieved catharsis through pity and terror.', 'She found writing her memoir to be a profound catharsis after decades of silence.'],
   herKu:['Ji bo Aristoteles, trajediya Yewnanî bi dilovanî û tirsê paqijbûna-hestî bi dest dixist.', 'Wê dît ku nivîsandina bîrnameya wê piştî deh salan bêdengî paqijbûneke-hestî ya kûr bû.'], emoji:'💧'),

