  (id:'en_c2_723', en:'nihilism', ku:'tunevanî', ipa:'/ˈnaɪɪlɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.50,
   notKu:'Ji Latînî nihil (tu tişt). (1) Felsefe: red a wateyan, nirxan, an rastî ya objektîf. (2) Siyaset: hereketa radikal a Rûsyayê ya sedsala 19em (Turgenev, "Fathers and Sons"). Nîçe wê teşxîs kir lê xwest jê derbas bibe, ne ku wê bipejirîne.',
   her:['Nietzsche diagnosed European culture as drifting toward nihilism after "the death of God".', 'The novel\'s protagonist descends into moral nihilism after losing his faith.'],
   herKu:['Nîçe çanda Ewropayî wek derbasbûyî ber bi tunevaniyê ve piştî "mirina Xwedê" teşxîs kir.', 'Qehremanê romanê piştî winda-kirina bawerî ya xwe ket nav tunevaniya exlaqî.'], emoji:'🕳️'),

  (id:'en_c2_724', en:'hedonism', ku:'kêfparêzî', ipa:'/ˈhiːdənɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.50,
   notKu:'Ji Yewnanî hēdonē (kêf): ramana ku kêf ya herî baş e. NOT: Epicureanism pirî caran bi xeletî bi vê re tê tevlihev kirin; Epikuros bi rastî ataraxia (aramiya derûnî) parast, ne kêfa hestî. Psîkolojî: hedonism yek ji teoriyên motîvasyonê ye.',
   her:['Utilitarian hedonism reduces ethical calculation to maximising pleasure and minimising pain.', 'Consumer culture has been accused of promoting a shallow hedonism.'],
   herKu:['Kêfparêziya sûdparêz hesabê exlaqî dadixe nav mezinkirina kêfê û kêmkirina êşê.', 'Çanda serfkariyê bi pêşxistina kêfparêziyeke hêşîn hatiye tometbar kirin.'], emoji:'🍷'),

  (id:'en_c2_725', en:'Stoicism', ku:'Stoîsîzm', ipa:'/ˈstəʊɪsɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.50,
   notKu:'Ji Yewnanî stoa poikilē (galeriya berwar a Atîna, cihê waneyê Zeno). Felsefeya hekîm-hekîm ya Helenîstîk: vîrtû ya tenê tiştê rastîn e, xemên derve ne-di-kontrola me de ne. Marcus Aurelius, Epictetus, Seneca. Tîpa S-ya mezin dema dibêjin dibistana felsefî.',
   her:['Marcus Aurelius\' "Meditations" remains the most accessible introduction to Stoicism.', 'Modern Stoicism has been revived by authors like Ryan Holiday and Donald Robertson.'],
   herKu:['"Meditations"-a Marcus Aurelius hîn jî gihîştî-ya herî baş a Stoîsîzmê ye.', 'Stoîsîzma nûjen bi nivîskarên wek Ryan Holiday û Donald Robertson ji nû ve hatiye vejandin.'], emoji:'🗿'),

  (id:'en_c2_726', en:'utilitarianism', ku:'sûdparêzî', ipa:'/juːˌtɪlɪˈteəriənɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.55,
   notKu:'Teoriyeke exlaqê encamparêz a sedsala 19em: Jeremy Bentham ("the greatest happiness of the greatest number") û John Stuart Mill di "Utilitarianism" (1863) de pêşxist. Rexneyên sereke: doza piraniyê dikare zilmê bide kêmaniyan.',
   her:['The trolley problem exposes a fundamental tension in utilitarianism.', 'Mill\'s qualitative utilitarianism distinguished "higher" from "lower" pleasures.'],
   herKu:['Pirsgirêka trolleyê tengahiyeke bingehîn di sûdparêziyê de eşkere dike.', 'Sûdparêziya Mill a kalîte kêfxweşiyên "jorîn" ji "jêrîn" cuda kir.'], emoji:'⚖️'),

  (id:'en_c2_727', en:'dualism', ku:'dualîzm', ipa:'/ˈdjuːəlɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.50,
   notKu:'Dualîzm. Du prensîbên bingehîn.',
   her:["Cartesian dualism separates mind and body.", "Dualism persists in philosophy."],
   herKu:['Dualîzma Kartezî mejî û laş vediqetîne.', 'Dualîzm di felsefeyê de berdewam e.'], emoji:'☯️'),

  (id:'en_c2_728', en:'monism', ku:'yekparêzî', ipa:'/ˈmɒnɪzəm/', pos:'n',
   form:null, kat:'felsefe', zor:0.60,
   notKu:'Yekparêzî. Hebûna yek prensîbî.',
