   notKu:'Arkaîk, pirî caran di Încîla King James de tê dîtin ("Verily I say unto you"). Di Îngilîzî ya nûjen de qet nayê bikaranîn ji bilî bi hendik-henekî an di çîrokên serdema kevn de. Register: tenê arkaîk/dînî.',
