  (id:'en_c2_804', en:'bathos', ku:'daketina-ji-bilindî', ipa:'/ˈbeɪθɒs/', pos:'n',
   form:null, kat:'edebî', zor:0.78,
   notKu:'Ji Yewnanî bathos (kûrahî). Di edebiyatê: daketina ji tonekî bilind/giran ber bi rêzê/pispisî — pirî caran bê qestî, dihêle ku nivîs xerab bê. Cuda ye ji pathos (keder).',
   her:['Alexander Pope\'s "Peri Bathous" (1727) satirised literary bathos in contemporary poetry.', 'The noble speech fell into bathos with "and finally, remember to recycle."'],
   herKu:['"Peri Bathous"-a Alexander Pope (1727) daketina-ji-bilindî ya di helbesta hevdem de şirît kir.', 'Axaftina esîl bi "û di dawiyê de, ji bîr mekin ku ji nû vereser bikin" ket nav daketina-ji-bilindî.'], emoji:'⤵️'),

