  (id:'en_c2_811', en:'palimpsest', ku:'çîn-li-ser-çîn', ipa:'/ˈpælɪmpsest/', pos:'n',
   form:null, kat:'edebî', zor:0.78,
   notKu:'Ji Yewnanî palimpsēstos (dîsa jêkirî): pargîdana parşomenê ya ku nivîsa kevin jê hate jêkirin û ya nû li ser hate nivîsandin — lê şopên yên kevn xwe nîşan didin. Mecazî: ya ku gelek çînên wateyî/dîrokî hene.',
   her:['Jerusalem is a palimpsest of civilisations: Canaanite, Jewish, Roman, Byzantine, Islamic, Crusader.', 'The restored manuscript revealed a palimpsest with an earlier classical text beneath.'],
   herKu:['Orşelîm çîn-li-ser-çînê şaristaniyên e: Ken\'anî, Cihûyî, Romî, Bîzansî, Îslamî, Xaçperest.', 'Destnivîsa sax-kirî çîn-li-ser-çînek bi nivîseke klasîk a berê ya di binê wê de eşkere kir.'], emoji:'📜'),

  // NOT: 'zeitgeisty' di Merriam-Webster/OED de hê ne-naskirî ye — colloquial neologîzm. Li şûnê 'risible' (edebî, OED) hat danîn.
  (id:'en_c2_812', en:'risible', ku:'ken-kêş', ipa:'/ˈrɪzəbl̩/', pos:'adj',
   form:null, kat:'edebî', zor:0.70,
   notKu:'Latînî risibilis (ji ridere = kenîn): edebî/formal; ya ku hêjaî kenê satirîk e, pirî caran ji ber bêmantiqiyê an bê-ciddî-tiyê. Register: formal, nêrîneke piçûkxistî dihewîne.',
   her:['The government\'s risible attempts at denial only worsened the scandal.', 'His risible claim of expertise after a single weekend course was embarrassing.'],
   herKu:['Hewldanên hikûmetê yên ken-kêş ên înkarê tenê skandal xirabtir kirin.', 'Îdiaya wî ya ken-kêş a pisporiyê piştî tenê kursa hefteyekê şermok bû.'], emoji:'😂'),

  // NOT: Duplicate ye — apocryphal jixwe heye (c2_482). Li şûnê 'discomfit' (arkaîk formal) hat danîn.
