   form:null, kat:'edebî', zor:0.65,
   notKu:'Arkaîk/edebî: bi lez-û-bez şaşvan kirin, bêçek kirin. Pirî caran bi passive tê bikaranîn (he was discomfited). NOT: bi "discomfort" re tevlihev neke — wateyên wan cuda ne.',
   her:['The witness was visibly discomfited by the cross-examination.', 'Her pointed question discomfited even the seasoned diplomat.'],
   herKu:['Şahid bi lêpirsîna hevtar xuya aciz-kirin bû.', 'Pirsa wê ya hûrsal heta dîplomatê bi-tecrube aciz-kir.'], emoji:'😳'),

